#!/usr/bin/env python3
"""Wrap docs/etube-tap-guide.html (page body, as published to claude.ai) in a full
HTML document so it opens directly in a browser and works on GitHub Pages.

Run: python3 tools/build_docs.py   ->  writes docs/index.html
"""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
SRC = ROOT / "docs" / "etube-tap-guide.html"
OUT = ROOT / "docs" / "index.html"

HEAD = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<!-- Generated by tools/build_docs.py from etube-tap-guide.html. Edit that file instead. -->
<style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style>
"""


def main():
    body = SRC.read_text(encoding="utf-8")
    # <title>, <meta>, <link> and <style> from the page belong in <head>
    split = body.index('<div class="shell">')
    OUT.write_text(HEAD + body[:split] + "</head>\n<body>\n" + body[split:] + "\n</body>\n</html>\n",
                   encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
